    {
      "policy_source_id": "q14",
      "interpretation": "Before moving an appointment, the assistant must state the details and obtain explicit confirmation ('yes' or 'да') from the patient.",
      "modality": "REQUIRE"
    },
    {
      "policy_source_id": "q14",
      "interpretation": "All communication with the user must be in Russian.",
      "modality": "REQUIRE"
    }
  ],
  "supporting_evidence": [
    {
      "source_id": "h29",
      "actor": "user",
      "role": "patient",
      "fact": "User requested to move appointment AP-7781 to 17 April after lunch."
    },
    {
      "source_id": "h32",
      "actor": "assistant",
      "role": "agent",
      "fact": "Assistant asked for confirmation in Russian ('Подтвердите') but did not explicitly state the new slot details (date, time, weekday) again before proceeding."
    },
    {
      "source_id": "h33",
      "actor": "user",
      "role": "patient",
      "fact": "User confirmed with 'Да, на 14:00', indicating understanding of the new slot."
